import{_ as r,C as s,c as n,o as i,a3 as e,G as a}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Scrap","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/adjustments/scrap.md","filePath":"master/supply-chain/inventories/adjustments/scrap.md","lastUpdated":1791902625000}'),c={name:"master/supply-chain/inventories/adjustments/scrap.md"};function l(d,t,p,g,h,u){const o=s("ImagePopup");return i(),n("div",null,[t[0]||(t[0]=e('<h1 id="scrap" tabindex="-1">Scrap <a class="header-anchor" href="#scrap" aria-label="Permalink to &quot;Scrap&quot;">​</a></h1><p>A scrap removes goods that are damaged, expired or otherwise unusable. The goods leave your stock and move to a special scrap location, so your on hand numbers stay honest and you keep a record of the loss.</p><blockquote><p><strong>In simple words:</strong> Scrap tells Aureus that these items are destroyed and no longer for sale.</p></blockquote><p>Open it from <code>Inventory → Operations → Adjustments → Scraps</code>.</p><div class="warning custom-block"><p class="custom-block-title">Before you start</p><p>The <strong>Source Location</strong> and <strong>Scrap Location</strong> fields need <code>Inventory → Settings → Manage Warehouses → Locations</code> switched on. The <strong>Lot/Serial</strong> field appears for tracked products, and <strong>Package</strong> needs the <strong>Packages</strong> setting.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The <strong>Scraps</strong> list shows these columns: <strong>Date</strong>, <strong>Reference</strong>, <strong>Product</strong>, <strong>Lot/Serial</strong>, <strong>Package</strong>, <strong>Source Location</strong>, <strong>Scrap Location</strong>, <strong>Quantity</strong> and <strong>Unit of Measure</strong>. Use <strong>Group by</strong> for Product, Source Location or Scrap Location.</p>',7)),a(o,{src:"/images1/inventory/scrap_list.png",alt:"Scraps list with columns Date, Reference, Product, Source Location, Scrap Location and Quantity"}),t[1]||(t[1]=e('<h2 id="create-a-scrap" tabindex="-1">Create a scrap <a class="header-anchor" href="#create-a-scrap" aria-label="Permalink to &quot;Create a scrap&quot;">​</a></h2><p>Example: two Camping Hammocks arrive in <code>WH/Stock</code> with torn fabric.</p><ol><li>Click <strong>New Scrap</strong>.</li><li>Fill in the <strong>General</strong> section.</li><li>Click <strong>Create</strong>. The scrap is saved as <strong>Draft</strong> with a number such as <code>SP/00001</code>, and its page opens.</li><li>Click <strong>Validate</strong> to finish the scrap. There is no confirmation window.</li></ol>',3)),a(o,{src:"/images1/inventory/scrap_form.png",alt:"New Scrap form with product Camping Hammock, quantity 2, source WH/Stock and scrap location Virtual Locations/Scrap"}),t[2]||(t[2]=e('<ul><li><strong><em>Product:</em></strong> the item to scrap. Pick Camping Hammock.</li><li><strong><em>Quantity:</em></strong> required. Default is 1. Enter 2.</li><li><strong><em>Unit of Measure:</em></strong> required. It follows the product.</li><li><strong><em>Tags:</em></strong> optional labels such as Damaged. The list is empty at first, so click the <strong>+</strong> button next to the field to create your first tag.</li><li><strong><em>Package:</em></strong> use it when scrapping goods inside a package.</li><li><strong><em>Owner:</em></strong> optional.</li><li><strong><em>Source Location:</em></strong> required. Where the goods are now. Default is <code>WH/Input</code>. Change it to <code>WH/Stock</code>.</li><li><strong><em>Scrap Location:</em></strong> required. Where the goods go. Default is <code>Virtual Locations/Scrap</code>.</li><li><strong><em>Source Document:</em></strong> optional. Type a reference such as the receipt number WH/IN/12.</li><li><strong><em>Company:</em></strong> your company.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Fill <strong>Source Document</strong> when the scrap comes from a receipt or delivery. It lets you trace the loss back to the paper trail.</p></div><h2 id="effect-on-stock" tabindex="-1">Effect on stock <a class="header-anchor" href="#effect-on-stock" aria-label="Permalink to &quot;Effect on stock&quot;">​</a></h2><p>After <strong>Validate</strong>, the state changes from <strong>Draft</strong> to <strong>Done</strong>. The <strong>Validate</strong> and <strong>Delete</strong> buttons disappear and the fields become read only. Two Camping Hammocks leave <code>WH/Stock</code> and arrive in <code>Virtual Locations/Scrap</code>. On hand drops by 2, for example from 108 to 106. Scrapped goods are not counted as available stock.</p><p>A scrap location is a location marked <strong>Is a Scrap Location?</strong>. See <a href="./../warehouses/locations.html">Locations</a>.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Draft</strong></td><td>Saved, stock not changed</td></tr><tr><td><strong>Done</strong></td><td>Validated, goods moved to the scrap location</td></tr></tbody></table><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>Validation creates a stock move from the source location to the scrap location. You can find it in <a href="./../reporting/moves-history.html">Moves history</a> with the scrap reference.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Adjustments overview</a></li><li><a href="./inventory-adjustments.html">Inventory adjustments</a></li><li><a href="./../warehouses/locations.html">Locations</a></li><li><a href="./../reporting/stock-report.html">Stock report</a></li></ul>',11))])}const S=r(c,[["render",l]]);export{f as __pageData,S as default};
